#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Generate the offline Cargo licence bundle; --check fails on drift."""
import argparse
import json
from pathlib import Path
import re
import subprocess

ROOT = Path(__file__).resolve().parent.parent


def generate():
    metadata = json.loads(subprocess.check_output(
        ["cargo", "metadata", "--offline", "--locked", "--format-version", "1",
         "--filter-platform", "x86_64-pc-windows-gnu"], cwd=ROOT, text=True))
    sections = [
        "# Third-party licences\n# Generated by scripts/generate-third-party-licenses.py.\n"
        "# Cargo.lock registry packages for x86_64-pc-windows-gnu (including build dependencies).\n"
        "# The Rust dependency notices also accompany MSVC releases.\n"
        "# GNU runtime terms are described separately in THIRD_PARTY.md.\n\n"
    ]
    for package in sorted(metadata["packages"], key=lambda p: (p["name"], p["version"])):
        if not (package.get("source") or "").startswith("registry+"):
            continue
        directory = Path(package["manifest_path"]).parent
        files = {p for p in directory.iterdir() if p.is_file() and re.match(
            r"^(LICENSE|LICENCE|COPYING|COPYRIGHT|NOTICE|UNLICENSE)", p.name, re.I)}
        if package.get("license_file"):
            files.add(directory / package["license_file"])
        if not files and package["name"] == "winapi-x86_64-pc-windows-gnu":
            # This import-library crate omits licence files; the parent winapi
            # crate ships the texts for the same winapi-rs repository/terms.
            parent = next(p for p in metadata["packages"] if p["name"] == "winapi")
            if parent["repository"] != package["repository"] or parent["license"] != package["license"]:
                raise RuntimeError("winapi licence provenance changed")
            files = set(Path(parent["manifest_path"]).parent.glob("LICENSE-*"))
        if not files:
            raise RuntimeError(f"No licence text for {package['name']} {package['version']}")
        sections.append("=" * 78 + "\n" + f"{package['name']} {package['version']}\n"
                        + f"License: {package['license']}\n" + "=" * 78 + "\n")
        for path in sorted(files, key=lambda p: p.name):
            sections.append(f"--- {path.name} ---\n" + path.read_text(encoding="utf-8").rstrip() + "\n\n")
    return "".join(sections).rstrip() + "\n"


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail instead of rewriting a stale bundle")
    args = parser.parse_args()
    content = generate()
    output = ROOT / "THIRD_PARTY_LICENSES.txt"
    if args.check:
        if not output.is_file() or output.read_text(encoding="utf-8") != content:
            parser.exit(1, "THIRD_PARTY_LICENSES.txt is stale; run scripts/generate-third-party-licenses.py\n")
        print("THIRD_PARTY_LICENSES.txt is up to date")
    else:
        output.write_text(content, encoding="utf-8", newline="\n")
        print("Wrote THIRD_PARTY_LICENSES.txt")


if __name__ == "__main__":
    main()
